import { Dashboard } from './js/Dashboard.js';
import { ToDoWidget } from './js/ToDoWidget.js';
import { FocusWidget } from './js/FocusWidget.js';
import { RhythmWidget } from './js/RhythmWidget.js';
import { WeatherWidget } from './js/WeatherWidget.js';
import { AirWidget } from './js/AirWidget.js';
import { HabitWidget } from './js/HabitWidget.js';
import { NoteWidget } from './js/NoteWidget.js';
import { QuoteWidget } from './js/QuoteWidget.js';
import { CalendarWidget } from './js/CalendarWidget.js';
import { ScheduleWidget } from './js/ScheduleWidget.js';
import { ProjectsWidget } from './js/ProjectsWidget.js';
import { BoardWidget } from './js/BoardWidget.js';
import { DeadlinesWidget } from './js/DeadlinesWidget.js';
import { HabitTrackerWidget } from './js/HabitTrackerWidget.js';
import { AnalyticsWidget } from './js/AnalyticsWidget.js';
import { icon } from './js/icons.js';
import { dayKey } from './js/storage.js';
import { dateOffset } from './js/WorkspaceStore.js';
import { makeElement as el } from './js/charts.js';
const lifecycle=new AbortController();
document.querySelector('#server-hint').hidden=true;
const on=(target,event,handler)=>target.addEventListener(event,handler,{signal:lifecycle.signal});
const entries=[['todo',ToDoWidget,'Задачи','Приоритеты и дела на выбранный день'],['rhythm',RhythmWidget,'Часы внимания','Активность за одну или две недели'],['focus',FocusWidget,'Фокус','Таймер с категориями занятий'],['calendar',CalendarWidget,'Календарь','Выбор даты и отметки событий'],['schedule',ScheduleWidget,'Расписание','События с временем и длительностью'],['projects',ProjectsWidget,'Проекты','Прогресс, описание и дедлайны'],['board',BoardWidget,'Доска задач','От плана к готовому результату'],['deadlines',DeadlinesWidget,'На горизонте','Ближайшие задачи проектов'],['habits',HabitTrackerWidget,'Привычки','Отметки по дням и неделям'],['heatmap',AnalyticsWidget,'Постоянство','Тепловая карта привычек'],['trend',AnalyticsWidget,'Динамика фокуса','Линейный график за 7, 14 или 30 дней'],['distribution',AnalyticsWidget,'Внимание','Кольцевая диаграмма категорий'],['balance',AnalyticsWidget,'Баланс проектов','Завершённые задачи проектов'],['note',NoteWidget,'Заметка','Место для мыслей'],['quote',QuoteWidget,'Мысль дня','Небольшое напоминание'],['weather',WeatherWidget,'Погода','Настоящие данные за окном'],['air',AirWidget,'Качество воздуха','Настоящий европейский индекс AQI'],['habit',HabitWidget,'Ритуалы первой версии','Независимые ежедневные отметки']];
const pages={overview:['Обзор','Хороший день для важного','Собери свой день из того, что имеет значение.'],plan:['План дня','Всё начинается с одного шага','Задачи, встречи и мысли — в одном ритме.'],projects:['Проекты','Идеи становятся реальностью','Большие замыслы. Маленькие, понятные шаги.'],habits:['Привычки','Маленькие действия. Большие перемены.','Постоянство без перфекционизма.'],analytics:['Аналитика','Посмотри на свой ритм','Замечай закономерности и находи свой баланс.']};
let dashboard,mode='demo',page='overview';
try{mode=localStorage.getItem('dayform.mode')==='personal'?'personal':'demo';}catch{}
function navigate(route){if(!pages[route])route='overview';if(location.hash!==`#${route}`)location.hash=route;else showPage(route,true);}
function showPage(route,focus=false){page=pages[route]?route:'overview';document.querySelectorAll('.route-page').forEach(section=>section.hidden=section.id!==`page-${page}`);document.querySelectorAll('[data-page]').forEach(link=>{const active=link.dataset.page===page;link.classList.toggle('active',active);if(active)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');});document.querySelector('#breadcrumb-page').textContent=pages[page][0].toUpperCase();const title=document.querySelector('#page-title');title.replaceChildren(document.createTextNode(pages[page][1]),el('span','greeting-star','✳'));document.querySelector('#page-subtitle').textContent=pages[page][2];document.title=`${pages[page][0]} · DAYFORM`;dashboard?.showPage(page);if(focus){title.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}}
function loadWorkspace(nextMode){if(dashboard)dashboard.destroy();document.querySelectorAll('.dashboard').forEach(container=>container.replaceChildren());mode=nextMode;try{localStorage.setItem('dayform.mode',mode);}catch{}dashboard=new Dashboard(document.querySelector('#overview-widgets'),{mode,navigate});entries.forEach(([type,Widget,title,description])=>dashboard.register(type,Widget,{title,description}));dashboard.restore();dashboard.currentPage=page;dashboard.events.addEventListener('data',renderMetrics,{signal:dashboard.lifecycle.signal});document.querySelectorAll('[data-mode]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.mode===mode)));document.querySelector('#demo-caption').textContent=mode==='demo'?'Пример заполненного пространства':'Твои данные, только в этом браузере';document.querySelector('#reset-workspace').textContent=mode==='demo'?'Сбросить демо':'Сбросить мои данные';document.querySelector('#arrange').setAttribute('aria-pressed','false');document.querySelectorAll('.dashboard').forEach(grid=>grid.classList.remove('arranging'));showPage(page);renderMetrics();}
function metric(title,value,unit,detail,tag,kind){const card=el('article','metric-card');const heading=el('div','metric-heading');const symbol=el('span','metric-icon');symbol.append(icon(kind));heading.append(symbol,el('span','',title));const number=el('div','metric-value',value);number.append(el('small','',unit));const foot=el('div','metric-foot');foot.append(el('span','',detail));if(tag)foot.append(el('span','metric-tag',tag));card.append(heading,number,foot);return card;}
function renderMetrics(){const tasks=dashboard.tasks;const today=dayKey();const todayTasks=tasks.filter(t=>t.date===today);const done=todayTasks.filter(t=>t.done).length;const minutes=dashboard.sessions.filter(s=>s.date===today).reduce((sum,s)=>sum+s.minutes,0);const habits=dashboard.store.data.habits;const habitDone=habits.filter(h=>h.days.includes(today)).length;const projects=dashboard.store.data.projects;const cards=dashboard.store.data.cards;const complete=cards.filter(c=>c.status==='done').length;const totalMinutes=dashboard.sessions.reduce((sum,s)=>sum+s.minutes,0);document.querySelector('#overview-metrics').replaceChildren(metric('Главное на сегодня',`${done}/${todayTasks.length}`,'задач','Маленькие шаги вперёд',todayTasks.length?`${Math.round(done/todayTasks.length*100)}% готово`:'Чистый лист','todo'),metric('Время для важного',minutes,'мин','Фокус сегодня',`${dashboard.sessions.filter(s=>s.date===today).length} сессии`,'focus'),metric('Твои ритуалы',`${habitDone}/${habits.length}`,'привычек','Забота о себе, каждый день',habitDone?'Хороший ритм':'Начни с малого','habits'));document.querySelector('#project-metrics').replaceChildren(metric('В движении',projects.length,'проектов','От идеи к результату','','projects'),metric('Завершено',complete,'задач','По всем проектам',cards.length?`${Math.round(complete/cards.length*100)}% готово`:'','todo'),metric('В работе',cards.filter(c=>c.status==='doing').length,'задач','То, что двигает тебя вперёд','','board'));const weekDays=Array.from({length:7},(_,i)=>dateOffset(-i));const weekCount=habits.reduce((sum,h)=>sum+h.days.filter(d=>weekDays.includes(d)).length,0);const streaks=habits.map(h=>{let streak=0;let offset=h.days.includes(today)?0:-1;while(streak<730&&h.days.includes(dateOffset(offset-streak)))streak++;return streak;});document.querySelector('#habit-metrics').replaceChildren(metric('Сегодня',habitDone,'отметки',`${habits.length} привычек в пространстве`,'','habits'),metric('За эту неделю',weekCount,'повторений','Последние семь дней',habits.length?`${Math.round(weekCount/(habits.length*7)*100)}%`:'','calendar'),metric('Лучшая текущая серия',Math.max(0,...streaks),'дней','Включая вчера, если день ещё идёт','','trend'));document.querySelector('#analytics-metrics').replaceChildren(metric('Всего внимания',Math.round(totalMinutes/60*10)/10,'часов',`${dashboard.sessions.length} завершённых сессий`,'','focus'),metric('Сделано',tasks.filter(t=>t.done).length+complete,'задач','Личные задачи и проекты','','todo'),metric('Привычки в действии',habits.reduce((sum,h)=>sum+h.days.length,0),'отметки','Каждое повторение считается','','habits'));}
document.querySelectorAll('[data-icon]').forEach(node=>node.append(icon(node.dataset.icon)));
document.querySelector('#date-label').textContent=new Date().toLocaleDateString('ru-RU',{day:'numeric',month:'long'});
showPage(location.hash.slice(1));loadWorkspace(mode);
on(window,'hashchange',()=>showPage(location.hash.slice(1),true));
document.querySelectorAll('[data-mode]').forEach(button=>on(button,'click',()=>{if(button.dataset.mode!==mode){loadWorkspace(button.dataset.mode);dashboard.announce(mode==='demo'?'Открыт демопример':'Открыты личные данные');}}));
on(document.querySelector('#reset-workspace'),'click',()=>{const message=mode==='demo'?'Сбросить демопример? Все изменения в демо будут удалены, и пример вернётся к изначальному состоянию.':'Сбросить мои данные? Все добавленные задачи, проекты, привычки, события, статистика и изменения расположения будут удалены. Пространство вернётся к изначальному состоянию. Это действие нельзя отменить.';if(!confirm(message))return;const resetMode=mode;if(dashboard){dashboard.destroy({save:false});dashboard=null;}try{localStorage.removeItem(`dayform.v2.${resetMode}`);if(resetMode==='personal')localStorage.removeItem('dayform.v1');}catch{}loadWorkspace(resetMode);dashboard.announce(resetMode==='demo'?'Демопример восстановлен до изначального состояния':'Мои данные сброшены до изначального состояния');});
const dialog=document.querySelector('#widget-dialog');let opener;
on(document.querySelector('#add-widget'),'click',event=>{opener=event.currentTarget;document.querySelector('#catalog-error').textContent='';dialog.showModal();});
on(dialog,'close',()=>{if(document.activeElement===document.body||dialog.contains(document.activeElement))opener?.focus();});
const options=document.querySelector('#widget-options');for(const[type,,title,description]of entries.filter(item=>item[0]!=='habit')){const button=el('button','widget-option');button.type='button';const symbol=el('span','option-symbol');symbol.append(icon(type));button.append(symbol,el('strong','',title),el('span','',description));on(button,'click',()=>{try{const widget=dashboard.addWidget(type,{page});dialog.close();widget.root.scrollIntoView({block:'nearest',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});widget.minimizeButton.focus();dashboard.announce(`Виджет «${widget.title}» добавлен`);}catch(error){document.querySelector('#catalog-error').textContent=error.message;}});options.append(button);}
on(document.querySelector('#arrange'),'click',event=>{dashboard.setArranging(!dashboard.arranging);event.currentTarget.setAttribute('aria-pressed',String(dashboard.arranging));});
on(document.querySelector('#quick-focus'),'click',()=>{let widget=dashboard.widgets.find(w=>w.type==='focus');if(!widget)widget=dashboard.addWidget('focus',{page:'overview',placement:'aside'});navigate(widget.page);if(widget.minimized)widget.minimize();requestAnimationFrame(()=>{widget.root.scrollIntoView({block:'center'});widget.start.focus();});});
on(document.querySelector('#help-button'),'click',()=>document.querySelector('#help-dialog').showModal());
on(document,'visibilitychange',()=>{if(document.hidden)dashboard.save();});
on(window,'pagehide',event=>{dashboard.save();if(!event.persisted){dashboard.destroy();lifecycle.abort();}});
if(document.modelContext?.registerTool){const tool={name:'dayform_add_task',title:'Добавить задачу в DAYFORM',description:'Добавляет задачу на выбранную дату в активное пространство DAYFORM (демопример или личные данные).',inputSchema:{type:'object',properties:{text:{type:'string',minLength:1,maxLength:180}},required:['text'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input.text!=='string'||!input.text.trim()||input.text.length>180||Object.keys(input).some(key=>key!=='text'))throw new Error('Ожидается текст задачи от 1 до 180 символов');const widget=dashboard.widgets.find(w=>w.type==='todo')??dashboard.addWidget('todo',{page:'plan'});return widget.addTask(input.text);}};try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(error=>console.warn('WebMCP unavailable',error));}catch(error){console.warn('WebMCP unavailable',error);}}
